DROP TABLE IF EXISTS `cameras`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cameras` (
  `camera_id` int NOT NULL AUTO_INCREMENT,
  `camera_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sensor_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_system` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lens_size_mm` decimal(5,2) DEFAULT NULL,
  `field_of_view_deg` int DEFAULT NULL,
  `interface_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mount_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight_g` int DEFAULT NULL,
  `supported_drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`camera_id`),
  UNIQUE KEY `camera_code` (`camera_code`),
  KEY `idx_camera_manufacturer` (`manufacturer_id`),
  KEY `idx_camera_type` (`camera_type`),
  KEY `idx_camera_resolution` (`resolution`),
  KEY `idx_camera_weight` (`weight_g`),
  KEY `idx_camera_interface` (`interface_type`),
  CONSTRAINT `fk_camera_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
