--
-- Table structure for table `chargers`
--

DROP TABLE IF EXISTS `chargers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chargers` (
  `charger_id` int NOT NULL AUTO_INCREMENT,
  `charger_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `charger_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_chemistry` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_charge_power_w` int DEFAULT NULL,
  `input_voltage` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `output_current` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `balancer_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_platform` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`charger_id`),
  UNIQUE KEY `charger_code` (`charger_code`),
  KEY `idx_chargers_manufacturer` (`manufacturer_id`),
  KEY `idx_chargers_power` (`max_charge_power_w`),
  KEY `idx_chargers_port` (`port_type`),
  CONSTRAINT `fk_chargers_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=480 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

