--
-- Table structure for table `drone_variants`
--

DROP TABLE IF EXISTS `drone_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drone_variants` (
  `variant_id` int NOT NULL AUTO_INCREMENT,
  `platform_id` int NOT NULL,
  `country_id` int NOT NULL,
  `variant_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `variant_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role_primary` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role_secondary` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `launch_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recovery_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `propulsion_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wingspan_m` decimal(6,2) DEFAULT NULL,
  `mtow_kg` decimal(8,2) DEFAULT NULL,
  `max_payload_kg` decimal(8,2) DEFAULT NULL,
  `endurance_hr` decimal(6,2) DEFAULT NULL,
  `operational_range_km` decimal(8,2) DEFAULT NULL,
  `datalink_range_km` decimal(8,2) DEFAULT NULL,
  `cruise_speed_kmh` decimal(6,2) DEFAULT NULL,
  `max_speed_kmh` decimal(6,2) DEFAULT NULL,
  `service_ceiling_m` int DEFAULT NULL,
  `power_source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `armament_capable` tinyint(1) DEFAULT NULL,
  `sensor_types` text COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`variant_id`),
  KEY `idx_variants_country` (`country_id`),
  KEY `idx_variants_platform` (`platform_id`),
  KEY `idx_variants_role_primary` (`role_primary`),
  KEY `idx_variants_launch_type` (`launch_type`),
  KEY `idx_variants_armament` (`armament_capable`),
  CONSTRAINT `drone_variants_ibfk_1` FOREIGN KEY (`platform_id`) REFERENCES `drone_platforms` (`platform_id`),
  CONSTRAINT `drone_variants_ibfk_2` FOREIGN KEY (`country_id`) REFERENCES `countries` (`country_id`)
) ENGINE=InnoDB AUTO_INCREMENT=246 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

