--
-- Table structure for table `esc`
--

DROP TABLE IF EXISTS `esc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `esc` (
  `esc_id` int NOT NULL AUTO_INCREMENT,
  `esc_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `esc_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `continuous_current_a` int DEFAULT NULL,
  `burst_current_a` int DEFAULT NULL,
  `supported_voltage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firmware` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `input_protocol` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mount_pattern` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bec_output` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cooling_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`esc_id`),
  UNIQUE KEY `esc_code` (`esc_code`),
  KEY `idx_esc_manufacturer` (`manufacturer_id`),
  KEY `idx_esc_current` (`continuous_current_a`),
  KEY `idx_esc_voltage` (`supported_voltage`),
  KEY `idx_esc_firmware` (`firmware`),
  KEY `idx_esc_protocol` (`input_protocol`),
  CONSTRAINT `fk_esc_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
