CREATE TABLE `esc_motor_compatibility` (
  `id` int NOT NULL AUTO_INCREMENT,
  `esc_id` int NOT NULL,
  `motor_id` int NOT NULL,
  `compatibility_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
