  KEY `idx_em_esc` (`esc_id`),
  KEY `idx_em_motor` (`motor_id`),
  CONSTRAINT `fk_em_esc` FOREIGN KEY (`esc_id`) REFERENCES `esc` (`esc_id`) ON DELETE CASCADE,
