DROP TABLE IF EXISTS `flight_controllers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight_controllers` (
  `flight_controller_id` int NOT NULL AUTO_INCREMENT,
  `fc_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `processor` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `form_factor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mounting` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firmware_supported` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imu` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barometer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `osd` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blackbox` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `esc_interface` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `connector_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`flight_controller_id`),
  UNIQUE KEY `fc_code` (`fc_code`),
  KEY `idx_fc_manufacturer` (`manufacturer_id`),
  KEY `idx_fc_processor` (`processor`),
  KEY `idx_fc_drone_type` (`supported_drone_type`),
  CONSTRAINT `fk_fc_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=529 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
