DROP TABLE IF EXISTS `frame_prop_compatibility`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `frame_prop_compatibility` (
  `id` int NOT NULL AUTO_INCREMENT,
  `frame_id` int NOT NULL,
  `propeller_id` int NOT NULL,
  `fit_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recommended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_pair` (`frame_id`,`propeller_id`),
  KEY `idx_fp_frame` (`frame_id`),
  KEY `idx_fp_prop` (`propeller_id`),
  CONSTRAINT `fk_fp_frame` FOREIGN KEY (`frame_id`) REFERENCES `frames` (`frame_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_fp_prop` FOREIGN KEY (`propeller_id`) REFERENCES `propellers` (`propeller_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1024 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

