--
-- Table structure for table `gps_modules`
--

DROP TABLE IF EXISTS `gps_modules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gps_modules` (
  `gps_id` int NOT NULL AUTO_INCREMENT,
  `gps_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gnss_support` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `compass_included` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_rate_hz` int DEFAULT NULL,
  `interface_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voltage_input` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `antenna_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mounting_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_firmware` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supported_drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`gps_id`),
  UNIQUE KEY `gps_code` (`gps_code`),
  KEY `fk_gps_manufacturer` (`manufacturer_id`),
  CONSTRAINT `fk_gps_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=513 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
