CREATE TABLE `motor_prop_compatibility` (
  `id` int NOT NULL AUTO_INCREMENT,
  `motor_id` int NOT NULL,
  `propeller_id` int NOT NULL,
  `compatibility_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recommended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_pair` (`motor_id`,`propeller_id`),
  KEY `idx_mp_motor` (`motor_id`),
  KEY `idx_mp_prop` (`propeller_id`),
  CONSTRAINT `fk_mp_motor` FOREIGN KEY (`motor_id`) REFERENCES `motors` (`motor_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mp_prop` FOREIGN KEY (`propeller_id`) REFERENCES `propellers` (`propeller_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2048 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
