DROP TABLE IF EXISTS `propellers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `propellers` (
  `propeller_id` int NOT NULL AUTO_INCREMENT,
  `prop_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prop_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diameter_in` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pitch_in` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blade_count` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `material` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mount_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rotation` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `compatible_drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`propeller_id`),
  UNIQUE KEY `prop_code` (`prop_code`),
  KEY `idx_propellers_type` (`prop_type`),
  KEY `idx_propellers_size` (`diameter_in`),
  KEY `idx_propellers_manufacturer` (`manufacturer_id`),
  CONSTRAINT `fk_propellers_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=481 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

