--
-- Table structure for table `rtf_uav`
--

DROP TABLE IF EXISTS `rtf_uav`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rtf_uav` (
  `rtf_id` int NOT NULL AUTO_INCREMENT,
  `manufacturer_id` int NOT NULL,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drone_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `build_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frame_size` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wheelbase` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motor_spec` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `propeller_spec` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_spec` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `flight_controller` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firmware` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payload_support` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_takeoff_kg` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intended_use` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`rtf_id`),
  KEY `idx_rtf_manufacturer` (`manufacturer_id`),
  KEY `idx_rtf_drone_type` (`drone_type`),
  KEY `idx_rtf_use` (`intended_use`),
  CONSTRAINT `fk_rtf_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `manufacturers` (`manufacturer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=483 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

