CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_batteries_csv`()
BEGIN

    /* =========================
       INSERT MANUFACTURERS
    ========================= */

    INSERT IGNORE INTO manufacturers (manufacturer_name)

    SELECT DISTINCT
        UPPER(TRIM(Brand))
    FROM battery_csv_staging
    WHERE Brand IS NOT NULL
      AND TRIM(Brand) != '';



    /* =========================
       INSERT BATTERIES
    ========================= */

    INSERT IGNORE INTO batteries (

        battery_code,
        manufacturer_id,
        sub_category,
        battery_chemistry,
        cell_count,
        voltage_v,
        capacity_mah,
        discharge_rate_c,
        energy_wh,
        connector_type,
        intended_use,
        compatible_drone_type
    )

    SELECT

        UPPER(TRIM(s.BatteryID)),

        m.manufacturer_id,

        TRIM(s.SubCategory),

        TRIM(s.BatteryChemistry),

        NULLIF(
            REGEXP_REPLACE(
                UPPER(TRIM(s.CellCount)),
                '[^0-9.]',
                ''
            ),
            ''
        ),

        NULLIF(
            REGEXP_REPLACE(
                UPPER(TRIM(s.Voltage_V)),
                '[^0-9.]',
                ''
            ),
            ''
        ),

        NULLIF(
            REGEXP_REPLACE(
                LOWER(TRIM(s.Capacity_mAh)),
                '[^0-9.]',
                ''
            ),
            ''
        ),

        NULLIF(
            REGEXP_REPLACE(
                UPPER(TRIM(s.DischargeRate_C)),
                '[^0-9.]',
                ''
            ),
            ''
        ),

        NULLIF(
            REGEXP_REPLACE(
                LOWER(TRIM(s.Energy_Wh)),
                '[^0-9.]',
                ''
            ),
            ''
        ),

        TRIM(s.ConnectorType),

        TRIM(s.IntendedUse),

        TRIM(s.CompatibleDroneType)

	FROM battery_csv_staging s

    JOIN manufacturers m
      ON UPPER(TRIM(m.manufacturer_name))
       = UPPER(TRIM(s.Brand))

    WHERE s.BatteryID IS NOT NULL
      AND TRIM(s.BatteryID) != '';



    /* =========================
       CLEAR STAGING
    ========================= */

    DELETE FROM battery_csv_staging;

END ;;
DELIMITER ;
