CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_drone_csv`()
BEGIN
    INSERT IGNORE INTO countries (country_name)
    SELECT DISTINCT Country FROM drone_csv_staging;

    INSERT IGNORE INTO manufacturers (manufacturer_name, sector)
    SELECT DISTINCT Manufacturer, Sector
    FROM drone_csv_staging;

    INSERT IGNORE INTO drone_platforms (
        base_platform_id,
        platform_name,
        manufacturer_id,
        drone_class,
        introduction_year,
        status
    )
    SELECT DISTINCT
        s.BasePlatformID,
        s.PlatformName,
        m.manufacturer_id,
        s.DroneClass,
        s.IntroductionYear,
        s.Status
    FROM drone_csv_staging s
    JOIN manufacturers m
      ON s.Manufacturer = m.manufacturer_name;

    INSERT INTO drone_variants (
        platform_id,
        country_id,
        variant_name,
        variant_type,
        role_primary,
        role_secondary,
        launch_type,
        recovery_type,
        propulsion_type,
        wingspan_m,
        mtow_kg,
        max_payload_kg,
        endurance_hr,
        operational_range_km,
        datalink_range_km,
        cruise_speed_kmh,
        max_speed_kmh,
        service_ceiling_m,
        power_source,
        armament_capable,
        sensor_types,
        notes
    )
    SELECT
        p.platform_id,
        c.country_id,
        s.VariantName,
        s.VariantType,
        s.RolePrimary,
        s.RoleSecondary,
        s.LaunchType,
        s.RecoveryType,
        s.PropulsionType,
        s.Wingspan_m,
        s.MTOW_kg,
        s.MaxPayload_kg,
        s.Endurance_hr,
        s.OperationalRange_km,
        s.DataLinkRange_km,
        s.CruiseSpeed_kmh,
        s.MaxSpeed_kmh,
        s.ServiceCeiling_m,
        s.PowerSource,
        IF(s.ArmamentCapable = 'Yes', TRUE, FALSE),
        s.SensorTypes,
        s.Notes
    FROM drone_csv_staging s
    JOIN drone_platforms p
      ON s.PlatformName = p.platform_name
    JOIN countries c
      ON s.Country = c.country_name;
END ;;
DELIMITER ;
