CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_radios_csv`()
BEGIN
    DECLARE done INT DEFAULT 0;

    DECLARE v_code VARCHAR(20);
    DECLARE v_brand VARCHAR(100);
    DECLARE v_device VARCHAR(100);
    DECLARE v_protocol VARCHAR(100);
    DECLARE v_freq VARCHAR(50);
    DECLARE v_channels VARCHAR(20);
    DECLARE v_telemetry VARCHAR(20);
    DECLARE v_antenna VARCHAR(100);
    DECLARE v_connector VARCHAR(100);
    DECLARE v_power VARCHAR(50);
    DECLARE v_supported VARCHAR(100);
    DECLARE v_use VARCHAR(150);

    DECLARE cur CURSOR FOR
        SELECT
            RadioID,
            Brand,
            DeviceType,
            Protocol,
            Frequency,
            ChannelCount,
            Telemetry,
            AntennaType,
            Connector,
            PowerOutput,
            Supported,
            IntendedUse
        FROM radio_csv_staging;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO
            v_code,
            v_brand,
            v_device,
            v_protocol,
            v_freq,
            v_channels,
            v_telemetry,
            v_antenna,
            v_connector,
            v_power,
            v_supported,
            v_use;

        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        IF v_code IS NULL OR TRIM(v_code) = '' THEN
            ITERATE read_loop;
        END IF;

        INSERT IGNORE INTO manufacturers (manufacturer_name)
        VALUES (TRIM(v_brand));

        INSERT IGNORE INTO radios_receivers (
            radio_code,
            manufacturer_id,
            device_type,
            protocol,
            frequency,
            channel_count,
            telemetry,
            antenna_type,
            connector,
            power_output,
            supported_drone_type,
            intended_use
        )
        SELECT
            TRIM(v_code),
            m.manufacturer_id,
            TRIM(v_device),
            TRIM(v_protocol),
            TRIM(v_freq),
            TRIM(v_channels),
            TRIM(v_telemetry),
            TRIM(v_antenna),
            TRIM(v_connector),
            TRIM(v_power),
            TRIM(v_supported),
            TRIM(v_use)
        FROM manufacturers m
        WHERE m.manufacturer_name = TRIM(v_brand);

    END LOOP;

    CLOSE cur;
    TRUNCATE radio_csv_staging;
END ;;
DELIMITER ;
